  );
}

collectMarkdownLinkSources(
  mdLink: string,
  filePath: string,
  siteDir: string,
  contentPaths: ContentPaths,
): string[] {
  const sourcesToTry: string[] = [];
  const relativePrefixes = this.linkPolicy.relativePrefixes;
  if (
    !mdLink.startsWith(relativePrefixes[0]) &&
    !mdLink.startsWith(relativePrefixes[1])
  ) {
    sourcesToTry.push(...this.getContentPathList(contentPaths), siteDir);
  }
  if (!mdLink.startsWith(this.linkPolicy.absolutePrefix)) {
    sourcesToTry.push(path.dirname(filePath));
  }
  return sourcesToTry;
}

resolveAliasedPermalink(
  sourcesToTry: string[],
  mdLink: string,
  siteDir: string,
  sourceToPermalink: {[aliasedPath: string]: string},
): string | undefined {
  return sourcesToTry
    .slice(this.linkPolicy.minSourceOffset)
    .map((candidate) => path.join(candidate, decodeURIComponent(mdLink)))
    .map((source) => this.aliasedSitePath(source, siteDir))
    .find((source) => sourceToPermalink[source]);
}

encodePermalinkSpaces(permalink: string): string {
  return permalink
    .split('/')
    .map((part) => part.replace(/\s/g, this.linkPolicy.spaceEncoding))
    .join('/');
}

recordBrokenMarkdownLink<T extends ContentPaths>(
  brokenMarkdownLinks: BrokenMarkdownLink<T>[],
  contentPaths: T,
  filePath: string,
  mdLink: string,
): void {
