  const extra = this.pathPolicy.appendingSpace;
  if (this.usesCharLengthLimit()) {
    return str.length + extra > this.pathPolicy.maxSegmentChars;
  }
  return (
    Buffer.from(str).length + extra > this.pathPolicy.maxSegmentBytes
  );
}

usesCharLengthLimit(): boolean {
  return (
    process.platform === this.pathPolicy.macPlatform ||
    process.platform === this.pathPolicy.windowsPlatform
