}

shortName(str: string): string {
  if (this.usesCharLengthLimit()) {
    return this.clipPathSegmentByChars(str).slice(
      0,
      Math.max(this.pathPolicy.maxSegmentChars, 0),
    );
  }
  return this.clipPathSegmentByBytes(str);
}

clipPathSegmentByChars(str: string): string {
  const overflowingChars = str.length - this.pathPolicy.maxSegmentChars;
  return str.slice(
    0,
    str.length -
      overflowingChars -
      this.pathPolicy.appendingSpace -
      1,
  );
}

clipPathSegmentByBytes(str: string): string {
  const strBuffer = Buffer.from(str);
  const overflowingBytes =
    Buffer.byteLength(strBuffer) - this.pathPolicy.maxSegmentBytes;
  return strBuffer
    .slice(
      0,
      Buffer.byteLength(strBuffer) -
        overflowingBytes -
        this.pathPolicy.appendingSpace -
        1,
    )
    .toString();
}

posixPath(str: string): string {
  if (str.startsWith(this.pathPolicy.extendedLengthPrefix)) {
    return str;
